type BuildTuple<N extends number> =
  Recur<N, []>;
type Recur<N extends number, Acc extends unknown[]> =
  Acc['length'] extends N ? Acc : [unknown, ...Recur<N, [unknown, ...Acc]>];
// recursive call wrapped in [unknown, ...] -> not tail position

diff.code:
type BuildTuple<N extends number, Acc extends unknown[] = []> =
  Acc['length'] extends N ? Acc : [unknown, ...BuildTuple<N, [unknown, ...Acc]>];

type Add<A extends number, B extends number> =
  [...BuildTuple<A>, ...BuildTuple<B>]['length'];

type Subtract<A extends number, B extends number> =
  BuildTuple<A> extends [...BuildTuple<B>, ...infer Rest]
    ? Rest['length']
    : never;

type X = Subtract<5, 2>;  // expected 3
